// v23.xx (gfx32), HIS ORDER 2026-10-12 (the graphics program, item 14, loot glow): A PILE WHOSE CONTENTS ARE KNOWN GLOWS ITS RARITY.
// HIS NOTE of 2026-08-26 stands untouched: a box you have not opened never tells you what it holds (the neutral amber pulse, the v8.99
// rule). The glow is only for loot whose contents everybody looking at it already knows: a pile somebody dropped (ct.dropped, your
// own or a teammate's), and an opened container that still has something left in it. Those now show a baked ground disc in the
// rarity colour of the best thing in them (RCOL, ranked by bestRarity, the displayed tier) with a lit lip along the top, pulsing
// gently, brighter for rare and up. A dropped pile shows that glow in place of the amber UNLOOTED pulse. A cache keeps its own
// landmark glow. Drawn with the container, so it sits under the darkness and the fog of war like the box itself.
function gfxLootSpr(r){
  var st=gfxStore('gfxEloot'), c, x, gr, col=RCOL[r]||RCOL.common;
  if(st.m[r]) return st.m[r];
  c=document.createElement('canvas'); c.width=c.height=64; x=c.getContext('2d');
  x.fillStyle=col; x.fillRect(0,0,64,64);
  x.globalCompositeOperation='destination-in';
  gr=x.createRadialGradient(32,32,0,32,32,32);
  gr.addColorStop(0,'rgba(0,0,0,1)'); gr.addColorStop(0.35,'rgba(0,0,0,.7)'); gr.addColorStop(0.7,'rgba(0,0,0,.22)'); gr.addColorStop(1,'rgba(0,0,0,0)');
  x.fillStyle=gr; x.fillRect(0,0,64,64);
  st.m[r]=c; st.n++;
  return c;
}
function gfxKnownBest(ct){
  if(!ct||ct.cache||!ct.loot||!ct.loot.length) return null;
  if(!(ct.dropped||ct.opened)) return null;   // HIS NOTE 2026-08-26: never before it is opened
  return bestRarity(ct.loot);
}
function gfxContPost(ct,w,lift,d2){
  if(!gfxHook('cont')) return false;
  var r=gfxKnownBest(ct); if(!r) return false;
  var rk=_RRANK[r]||0, pu=0.5+0.5*Math.sin((G.t||0)*2.6+ct.x*0.05), R=(rk>=2)?30:24, s=gfxLootSpr(r), top;
  wc.save();
  try{
    wc.globalCompositeOperation='lighter';
    wc.globalAlpha=((rk>=2)?0.62:(rk>=1?0.46:0.26))*(0.72+0.28*pu)*(ct.opened?0.8:1);
    wc.drawImage(s,ct.x-R,ct.y-R*0.45,R*2,R*0.9);
    if(ct.type!=='body'&&ct.type!=='botwreck'&&w>0){
      top=ct.y-lift-d2-(ct.opened?5:0);
      wc.globalAlpha=(rk>=1?0.75:0.45)*(0.6+0.4*pu); wc.fillStyle=RCOL[r]||RCOL.common;
      wc.fillRect(ct.x-w/2,top,w,1.5);
    }
  } finally { wc.restore(); }
  return true;
}
